def add(chapter,title,kind,**values):
 n=sum(a['chapter']==chapter for a in data['activities'])+1
 a={'id':chapter+'-'+str(n),'chapter':chapter,'title':title,'type':kind,**values};data['activities'].append(a);return a
serial=0
def q(prompt,answer,*others,why=None):
 global serial
 options=[answer,*others];offset=serial%len(options);serial+=1
 options=options[offset:]+options[:offset]
 return {'prompt':prompt,'options':options,'answer':options.index(answer),'explanation':why or prompt.replace('___',answer)}
def yn(prompt,yes,why):return q(prompt,'نَعَمْ' if yes else 'لَا','لَا' if yes else 'نَعَمْ',why=why)
def star(cx,cy,r=18,points=5):
 return ' '.join(f'{cx+(r if i%2==0 else r*.43)*math.sin(i*math.pi/points):.2f},{cy-(r if i%2==0 else r*.43)*math.cos(i*math.pi/points):.2f}' for i in range(points*2))
