def obj(kind,x,y,s=1,color=None):return {'kind':kind,'x':x,'y':y,'scale':s,**({'color':color} if color else {})}
def scene(name,objects,label='',ground=True):
 body='<rect width="600" height="340" rx="22" fill="#f9f6e9"/>'
 if ground:body+='<path d="M0 285Q200 268 600 285V340H0Z" fill="#e4e9d4"/>'
 for o in objects:
  body+='<g transform="translate('+str(o['x'])+' '+str(o['y'])+') scale('+str(o['scale'])+')"'+(' style="--color:'+COLORS.get(o['color'],o['color'])+'"' if o.get('color') else '')+'>'+icon(o['kind'])+'</g>'
 if label:body+='<text x="300" y="322" font-family="Tahoma,sans-serif" text-anchor="middle" fill="#294c41" font-size="21">'+escape(label)+'</text>'
 path='images/reading-exercises/'+name+'.svg'
 (ROOT/path).write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 340" role="img">'+body+'</svg>')
 return path

