 if country=='jordan':
  parts.append(part('star','النَّجْمَةُ ذَاتُ الرُّؤُوسِ السَّبْعَةِ','white'));ins.append('اِجْعَلِ النَّجْمَةَ ذَاتَ الرُّؤُوسِ السَّبْعَةِ بَيْضَاءَ.');body+=region('polygon','star','points="'+star(113,170,24,7)+'"')
 if country=='syria':
  for i,x in enumerate([190,300,410],1):parts.append(part('star'+str(i),'النَّجْمَةُ '+str(i),'red'));body+=region('polygon','star'+str(i),'points="'+star(x,170,25)+'"')
  ins.append('لَوِّنِ النُّجُومَ الثَّلَاثَ الْمَوْجُودَةَ فِي الشَّرِيطِ الْأَبْيَضِ بِاللَّوْنِ الْأَحْمَرِ.')
 color_activity(title,parts,ins,body)
